<script setup lang="ts">
import { computed, inject, ref } from 'vue';
import { VISION } from '../vision';
import { vHover } from '../kit/hover';
import { PLACES, CONDITIONS, forecast, type ForecastDay } from './weather/model';
import Sky from './weather/Sky.vue';
import WeatherIcon from './weather/WeatherIcon.vue';
import CityList from './weather/CityList.vue';
import AppSheet from './arcade/AppSheet.vue';
defineProps<{ compact?: boolean }>();
const vision = inject(VISION)!;
const selected = ref('bengaluru');
const fahrenheit = ref(false);
const placesOpen = ref(false);
const minute = computed(() => Math.floor(vision.now.value.getTime() / 60000));
const now = computed(() => new Date(minute.value * 60000));
const city = computed(() => PLACES.find(place => place.id === selected.value) ?? PLACES[0]!);
const data = computed(() => forecast(city.value, now.value));
const minimum = computed(() => Math.min(...data.value.days.map(day => day.low)));
const maximum = computed(() => Math.max(...data.value.days.map(day => day.high)));
const daylight = computed(() => Math.max(0, Math.min(1, (data.value.hour - data.value.sunrise) / (data.value.sunset - data.value.sunrise))));
const sunPoint = computed(() => ({ x: 100 - 84 * Math.cos(Math.PI * daylight.value), y: 90 - 60 * Math.sin(Math.PI * daylight.value) }));
const uvName = computed(() => data.value.uv < 3 ? 'Low' : data.value.uv < 6 ? 'Moderate' : data.value.uv < 8 ? 'High' : 'Very high');
const airName = computed(() => data.value.aqi <= 50 ? 'Good' : 'Moderate');
function temp(value: number): string { return Math.round(fahrenheit.value ? value * 9 / 5 + 32 : value) + '°'; }
function range(day: ForecastDay): Record<string, string> { return { left: position(day.low) + '%', width: (day.high - day.low) / (maximum.value - minimum.value || 1) * 100 + '%' }; }
function position(value: number): number { return (value - minimum.value) / (maximum.value - minimum.value || 1) * 100; }
function select(id: string): void { selected.value = id; placesOpen.value = false; }
function sunTime(hour: number): string { const h = Math.floor(hour); return String(h).padStart(2, '0') + ':' + String(Math.round((hour - h) * 60)).padStart(2, '0'); }
</script>

<template>
<div class="weather-app" :class="{ compact }">
  <Sky :condition="city.condition" :hour="data.hour" :seed="city.seed" />
  <div class="weather-layout" :inert="placesOpen ? true : undefined">
    <aside class="sidebar vk-platter"><h1 class="vk-title">Weather</h1><CityList :selected="selected" :now="now" :fahrenheit="fahrenheit" @select="select" /></aside>
    <main class="forecast vk-scroll">
      <header class="forecast-toolbar"><button v-hover class="vk-button places-button" @click="placesOpen = true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1" /></svg>Places</button><span class="demo vk-chip">Demo forecast</span><div class="vk-segmented" role="group" aria-label="Temperature units"><button v-hover :aria-pressed="!fahrenheit" @click="fahrenheit = false">°C</button><button v-hover :aria-pressed="fahrenheit" @click="fahrenheit = true">°F</button></div></header>
      <section class="weather-hero"><p class="region vk-footnote">{{ city.region }}</p><h2>{{ city.name }}</h2><div class="temperature">{{ temp(data.current) }}</div><p class="vk-title condition">{{ CONDITIONS[city.condition] }}</p><p class="vk-body">H:{{ temp(data.high) }} &nbsp; L:{{ temp(data.low) }}</p></section>
      <section class="hourly panel vk-platter" aria-label="24-hour demo forecast"><p class="panel-title">THE NEXT 24 HOURS</p><p class="hourly-note vk-footnote">{{ city.condition === 'rain' ? 'A good day to give your umbrella a promotion.' : city.condition === 'snow' ? 'Small flakes. Big sweater energy.' : city.condition === 'storm' ? 'The sky has a percussion section today.' : city.condition === 'fog' ? 'The skyline is taking a soft-focus day.' : 'A forecast with room for a little wandering.' }}</p><div class="hours vk-scroll" tabindex="0" role="group" aria-label="Scrollable hourly forecast"><div v-for="(hour, index) in data.hours" :key="hour.key" class="hour" :class="{ current: index === 0 }"><strong>{{ hour.label }}</strong><WeatherIcon :condition="hour.condition" :night="hour.hour < 6 || hour.hour >= 19" /><small class="precip">{{ hour.precipitation > 20 ? hour.precipitation + '%' : ' ' }}</small><span>{{ temp(hour.temp) }}</span></div></div></section>
      <section class="panel daily vk-platter" aria-label="10-day demo forecast"><p class="panel-title">10-DAY FORECAST</p><div v-for="(day,index) in data.days" :key="day.key" class="day"><strong>{{ day.label }}</strong><div class="day-condition"><WeatherIcon :condition="day.condition" /><small v-if="day.precipitation > 20">{{ day.precipitation }}%</small></div><span class="vk-secondary">{{ temp(day.low) }}</span><div class="range-track" role="img" :aria-label="day.label + ': low ' + temp(day.low) + ', high ' + temp(day.high)"><i :style="range(day)" /><b v-if="index === 0" :style="{ left: position(data.current) + '%' }" /></div><span>{{ temp(day.high) }}</span></div></section>
      <div class="metrics">
        <section class="metric panel vk-platter"><p class="panel-title">UV INDEX</p><strong class="metric-value">{{ data.uv }}</strong><h3>{{ uvName }}</h3><div class="spectrum uv"><i :style="{ left: data.uv / 11 * 100 + '%' }" /></div><p>{{ data.uv >= 3 ? 'Sunscreen: yes. Excuses: no.' : 'The sun is keeping things gentle.' }}</p></section>
        <section class="metric wind panel vk-platter"><p class="panel-title">WIND</p><div class="wind-body"><div><strong class="metric-value">{{ data.wind }}</strong><small>km/h</small></div><svg viewBox="0 0 120 120" class="compass" role="img" :aria-label="'Wind from ' + data.bearing + ' degrees'"><circle cx="60" cy="60" r="44" fill="none" stroke="#ffffff30" stroke-dasharray="1 5" /><text x="60" y="13">N</text><text x="108" y="64">E</text><text x="60" y="117">S</text><text x="12" y="64">W</text><g :transform="'rotate(' + data.bearing + ' 60 60)'" fill="none" stroke="#d1eeff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M60 90V30m-9 12 9-12 9 12" /><circle cx="60" cy="60" r="4" fill="#e7f5ff" /></g></svg></div><p>Hair with a plot twist.</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">HUMIDITY</p><strong class="metric-value">{{ data.humidity }}<small>%</small></strong><div class="humidity-drops" aria-hidden="true"><svg v-for="i in 8" :key="i" viewBox="0 0 12 18" :class="{ filled: i <= Math.round(data.humidity / 12.5) }"><path d="M6 1C6 1 1 8 1 11a5 5 0 0 0 10 0C11 8 6 1 6 1Z" /></svg></div><p>Dew point {{ temp(data.dew) }}. The air is feeling clingy.</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">SUNRISE & SUNSET</p><div class="sun-times"><strong>{{ sunTime(data.sunrise) }}</strong><strong>{{ sunTime(data.sunset) }}</strong></div><svg class="sun-arc" viewBox="0 0 200 105" role="img" :aria-label="'Sunrise ' + sunTime(data.sunrise) + ', sunset ' + sunTime(data.sunset)"><path d="M16 90C16 10 184 10 184 90" fill="none" stroke="#fff2a95c" stroke-width="2" /><path d="M6 90h188" stroke="#ffffff40" stroke-dasharray="3 4" /><path d="M16 90a84 60 0 0 1 168 0" fill="none" stroke="#ffe5aa" stroke-width="2" /><circle :cx="sunPoint.x" :cy="sunPoint.y" r="7" fill="#ffe5aa" /></svg><p>{{ data.hour < data.sunrise || data.hour > data.sunset ? 'The sun has clocked out. You may too.' : 'A daily show. No ticket required.' }}</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">FEELS LIKE</p><strong class="metric-value">{{ temp(data.feels) }}</strong><h3>{{ data.feels === data.current ? 'Just as it looks' : data.feels < data.current ? 'A little cooler' : 'A little warmer' }}</h3><p>Your sleeves may have an opinion.</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">AIR QUALITY</p><strong class="metric-value">{{ data.aqi }}</strong><h3>{{ airName }} <small>· Demo AQI</small></h3><div class="spectrum air"><i :style="{ left: data.aqi / 150 * 100 + '%' }" /></div><p>{{ airName === 'Good' ? 'A fictional deep breath of fresh air.' : 'Even imaginary air has its off days.' }}</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">VISIBILITY</p><strong class="metric-value">{{ data.visibility }}<small>km</small></strong><svg class="visibility-lines" viewBox="0 0 180 40" fill="none" stroke="#ffffff60" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M5 32h170M25 22h130M45 12h90M65 2h50" /></svg><p>{{ data.visibility < 5 ? 'The horizon pressed the snooze button.' : 'The horizon is accepting visitors.' }}</p></section>
        <section class="metric panel vk-platter"><p class="panel-title">PRESSURE</p><div class="pressure"><svg viewBox="0 0 160 90" aria-hidden="true"><path d="M15 80a65 65 0 0 1 130 0" fill="none" stroke="#ffffff40" stroke-width="9" stroke-dasharray="2 5" /><path d="M80 80V25" :transform="'rotate(' + ((data.pressure - 1010) * 3) + ' 80 80)'" stroke="#deedff" stroke-width="2" stroke-linecap="round" /><circle cx="80" cy="80" r="5" fill="#deedff" /></svg><strong>{{ data.pressure }} <small>hPa</small></strong></div><p>Under pressure. Still quite composed.</p></section>
      </div>
      <footer class="vk-footnote vk-secondary">Entirely generated demo data. No live weather service. City clocks use fixed UTC offsets; daylight saving changes are not applied.</footer>
    </main>
  </div>
  <AppSheet v-if="placesOpen" title="Choose a place" @close="placesOpen = false"><CityList :selected="selected" :now="now" :fahrenheit="fahrenheit" @select="select" /></AppSheet>
</div>
</template>

<style src="../kit/kit.css"></style>
<style scoped>
