.weather-layout { display: grid; grid-template-columns: 260px minmax(0,1fr); height: 100%; position: relative; } .sidebar { display: flex; flex-direction: column; gap: 24px; margin: 22px 0 22px 22px; padding: 22px 12px; min-height: 0; border-radius: 28px; } .sidebar h1 { padding: 0 8px; } .sidebar :deep(.city-list) { flex: 1; min-height: 0; } .forecast { padding: 22px 24px 30px; min-width: 0; }
.forecast-toolbar { display: flex; align-items: center; gap: 10px; justify-content: space-between; } .forecast-toolbar .vk-segmented button { min-width: 44px; min-height: 44px; padding: 0 12px; } .places-button { display: none; } .places-button svg { width: 20px; height: 20px; }
.weather-hero { text-align: center; padding: 30px 0; text-shadow: 0 2px 18px #14294040; } .weather-hero h2 { font-size: 32px; letter-spacing: -.025em; font-weight: 500; margin-top: 5px; } .region { color: #ffffffb5; } .temperature { font-size: 96px; font-weight: 200; line-height: 1.15; letter-spacing: -.065em; padding-left: 14px; } .weather-hero .condition { font-weight: 500; margin-bottom: 8px; }
.weather-app .panel { border-radius: 24px; padding: 18px; background-color: #172f4c38; } .panel-title { font-size: 11px; letter-spacing: .08em; color: #ffffffb8; font-weight: 600; margin-bottom: 14px; } .hourly-note { margin-bottom: 12px; color: #ffffffdf; } .hourly { margin-bottom: 16px; } .hours { display: flex; gap: 9px; padding-bottom: 3px; } .hour { flex: 0 0 57px; display: flex; flex-direction: column; align-items: center; gap: 5px; padding: 10px 6px; border-radius: 20px; } .hour.current { background: #ffffff21; } .hour strong { font-size: 14px; font-weight: 500; } .hour svg { width: 32px; height: 32px; } .precip { min-height: 15px; color: #a9dcff; font-size: 11px; } .hour > span { font-size: 21px; font-weight: 500; }
.daily { margin-bottom: 16px; } .day { display: grid; grid-template-columns: 46px 38px 34px minmax(30px,1fr) 34px; align-items: center; gap: 10px; min-height: 48px; border-top: 1px solid #ffffff12; font-variant-numeric: tabular-nums; } .day strong { font-size: 14px; font-weight: 500; } .day > span { text-align: right; font-size: 16px; } .day-condition { display: flex; flex-direction: column; align-items: center; } .day-condition svg { width: 27px; height: 27px; } .day-condition small { color: #b2e1ff; font-size: 9px; } .range-track { height: 6px; position: relative; border-radius: 8px; background: #08182b55; } .range-track i { position: absolute; top: 0; height: 100%; border-radius: inherit; background: linear-gradient(90deg,#68bbf6,#a5e2db,#f5d477,#f49f65); } .range-track b { position: absolute; top: 50%; transform: translate(-50%,-50%); width: 9px; height: 9px; border: 2px solid #2b4560; border-radius: 50%; background: white; }
.metrics { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 16px; } .metric { display: flex; flex-direction: column; min-width: 0; min-height: 190px; gap: 8px; } .metric .panel-title { margin-bottom: 0; } .metric-value { font-size: 42px; font-weight: 400; line-height: 1.1; letter-spacing: -.04em; } .metric-value small { font-size: 23px; margin-left: 3px; } .metric h3 { font-size: 17px; font-weight: 500; } .metric h3 small { font-size: 12px; } .metric > p:last-child { font-size: 13px; line-height: 1.45; margin-top: auto; color: #ffffffcc; } .spectrum { height: 5px; border-radius: 9px; margin: 8px 0 12px; position: relative; } .spectrum i { position: absolute; height: 11px; width: 5px; background: white; border-radius: 4px; top: -3px; box-shadow: 0 0 0 2px #203b58; } .uv { background: linear-gradient(90deg,#62ca9e,#e8d777,#f29a71,#c46eae); } .air { background: linear-gradient(90deg,#6bddcf,#e6d877,#df9880); }
.wind-body { display: flex; align-items: center; justify-content: space-between; gap: 4px; } .wind-body > div { display: flex; flex-direction: column; } .wind-body small { font-size: 14px; color: #ffffffab; } .compass { width: 106px; height: 106px; } .compass text { font: 10px sans-serif; fill: #ffffffb5; text-anchor: middle; } .humidity-drops { display: flex; gap: 6px; margin: 8px 0 16px; } .humidity-drops svg { width: 12px; height: 18px; fill: #ffffff25; } .humidity-drops .filled { fill: #a2dcff; } .sun-times { display: flex; justify-content: space-between; font-variant-numeric: tabular-nums; } .sun-times strong { font-size: 21px; font-weight: 400; } .sun-arc { width: 100%; height: 75px; } .visibility-lines { width: 100%; height: 36px; margin: 12px 0; } .pressure { position: relative; text-align: center; } .pressure svg { width: 130px; height: 74px; } .pressure strong { display: block; font-size: 24px; font-weight: 400; } .pressure small { font-size: 12px; } footer { padding: 24px 4px 0; line-height: 1.6; }
.weather-app :deep(.app-sheet .city-list) { height: auto; } .weather-app :deep(.app-sheet .places) { overflow: visible; flex: none; }
.compact .weather-layout { grid-template-columns: 1fr; } .compact .sidebar { display: none; } .compact .places-button { display: inline-flex; padding: 0 14px; } .compact .forecast { padding: 22px; } .compact .metrics { grid-template-columns: 1fr; } .compact .metric { min-height: 190px; } .compact .demo { font-size: 11px; padding: 0 10px; }
@container (max-width: 700px) { .weather-layout { grid-template-columns: 1fr; } .sidebar { display: none; } .places-button { display: inline-flex; } }
@container (min-width: 1150px) { .metrics { grid-template-columns: repeat(3,minmax(0,1fr)); } }
@container (max-width: 400px) { .forecast-toolbar { flex-wrap: wrap; } .demo { order: 3; } .day { gap: 7px; grid-template-columns: 40px 28px 28px minmax(20px,1fr) 28px; } .weather-app .panel { padding: 15px; } }
@media (prefers-reduced-motion: reduce) { .weather-app *, .weather-app *::before, .weather-app *::after { animation: none !important; transition: none !important; } }
</style>
